// Helper: si el valor es un objeto {es, en}, devuelve el texto en el idioma activo;
// si es un string plano (nombres propios, marcas, tecnologías), lo devuelve tal cual.
function tx(val, lang) {
  if (val && typeof val === "object" && (val.es || val.en)) return val[lang] ?? val.es ?? val.en;
  return val;
}

