// Revela un bloque con fade + desplazamiento cuando entra en el viewport.
function Reveal({ children, delay = 0, className = "", as: Tag = "div", ...rest }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          obs.disconnect();
        }
      },
      { threshold: 0.15 }
    );
    obs.observe(node);
    return () => obs.disconnect();
  }, []);

  return (
    <Tag
      ref={ref}
      className={`pf-reveal ${visible ? "pf-in-view" : ""} ${className}`}
      style={{ transitionDelay: `${delay}ms` }}
      {...rest}
    >
      {children}
    </Tag>
  );
}

// Cuenta de 0 al valor objetivo una vez que el elemento entra en pantalla.
function useCountUp(target, duration = 1400) {
  const ref = useRef(null);
  const [value, setValue] = useState(0);
  const started = useRef(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !started.current) {
          started.current = true;
          const start = performance.now();
          const tick = (now) => {
            const progress = Math.min((now - start) / duration, 1);
            const eased = 1 - Math.pow(1 - progress, 3);
            setValue(Math.round(eased * target));
            if (progress < 1) requestAnimationFrame(tick);
          };
          requestAnimationFrame(tick);
          obs.disconnect();
        }
      },
      { threshold: 0.4 }
    );
    obs.observe(node);
    return () => obs.disconnect();
  }, [target, duration]);

  return [ref, value];
}

// Efecto de escritura tipo terminal para el subtítulo del rol.
function useTypewriter(text, speed = 38, startDelay = 400) {
  const [out, setOut] = useState("");
  const [done, setDone] = useState(false);

  useEffect(() => {
    let i = 0;
    let timer;
    const startTimer = setTimeout(() => {
      timer = setInterval(() => {
        i += 1;
        setOut(text.slice(0, i));
        if (i >= text.length) {
          clearInterval(timer);
          setDone(true);
        }
      }, speed);
    }, startDelay);
    return () => {
      clearTimeout(startTimer);
      clearInterval(timer);
    };
  }, [text, speed, startDelay]);

  return [out, done];
}

// Barra de dominio técnico animada al entrar en pantalla.
function ProficiencyBar({ name, pct, delay = 0 }) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          obs.disconnect();
        }
      },
      { threshold: 0.3 }
    );
    obs.observe(node);
    return () => obs.disconnect();
  }, []);

  return (
    <div className="pf-prof-row" ref={ref}>
      <div className="pf-prof-top">
        <span className="pf-prof-name">{name}</span>
        <span className="pf-prof-pct pf-mono">{inView ? pct : 0}%</span>
      </div>
      <div className="pf-prof-track">
        <div
          className="pf-prof-fill"
          style={{
            width: inView ? `${pct}%` : "0%",
            transitionDelay: `${delay}ms`,
          }}
        />
      </div>
    </div>
  );
}

// Imagen con respaldo: si la fuente (p.ej. un escudo cargado desde una URL externa)
// falla al cargar, muestra un ícono/monograma de respaldo en su lugar.
function SafeImg({ src, alt, fallback, className }) {
  const [failed, setFailed] = useState(false);
  if (failed || !src) return fallback;
  return <img src={src} alt={alt} className={className} onError={() => setFailed(true)} />;
}

// Barra fina en la parte superior que se llena según el progreso de scroll.
function ScrollProgress() {
  const barRef = useRef(null);
  useEffect(() => {
    const onScroll = () => {
      const doc = document.documentElement;
      const scrolled = doc.scrollTop;
      const max = doc.scrollHeight - doc.clientHeight;
      const pct = max > 0 ? (scrolled / max) * 100 : 0;
      if (barRef.current) barRef.current.style.width = `${pct}%`;
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return (
    <div className="pf-scroll-track">
      <div className="pf-scroll-bar" ref={barRef} />
    </div>
  );
}

// Mini terminal que simula una consola de monitoreo en vivo, escribiendo línea
// por línea y haciendo scroll hacia arriba como un log real.
function LiveConsole({ lang }) {
  const [lines, setLines] = useState([]);
  const idxRef = useRef(0);
  const bodyRef = useRef(null);

  useEffect(() => {
    setLines([]);
    idxRef.current = 0;
  }, [lang]);

  useEffect(() => {
    const source = CONSOLE_LINES[lang] || CONSOLE_LINES.es;
    const timer = setInterval(() => {
      setLines((prev) => {
        const next = [...prev, source[idxRef.current % source.length]];
        idxRef.current += 1;
        return next.slice(-7);
      });
    }, 1100);
    return () => clearInterval(timer);
  }, [lang]);

  useEffect(() => {
    if (bodyRef.current) bodyRef.current.scrollTop = bodyRef.current.scrollHeight;
  }, [lines]);

  return (
    <div className="pf-console">
      <div className="pf-console-bar">
        <span className="pf-dot-row">
          <span className="pf-dot red" />
          <span className="pf-dot amber" />
          <span className="pf-dot green" />
        </span>
        <span className="pf-console-title">monitor.sh</span>
      </div>
      <div className="pf-console-body" ref={bodyRef}>
        {lines.map((l, i) => (
          <div className="pf-console-line" key={i}>
            {l}
          </div>
        ))}
        <span className="pf-caret pf-console-caret" />
      </div>
    </div>
  );
}

// Envoltorio que inclina su contenido en 3D siguiendo la posición del cursor,
// con un brillo que sigue el puntero. Se desactiva solo con CSS en touch/mobile.
function TiltCard({ children, className = "", maxTilt = 7 }) {
  const ref = useRef(null);

  const onMove = useCallback(
    (e) => {
      const el = ref.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const px = (e.clientX - rect.left) / rect.width;
      const py = (e.clientY - rect.top) / rect.height;
      const rx = (0.5 - py) * maxTilt * 2;
      const ry = (px - 0.5) * maxTilt * 2;
      el.style.transform = `perspective(700px) rotateX(${rx}deg) rotateY(${ry}deg) translateZ(0)`;
      el.style.setProperty("--glare-x", `${px * 100}%`);
      el.style.setProperty("--glare-y", `${py * 100}%`);
    },
    [maxTilt]
  );

  const onLeave = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    el.style.transform = "perspective(700px) rotateX(0deg) rotateY(0deg)";
  }, []);

  return (
    <div ref={ref} className={`pf-tilt ${className}`} onMouseMove={onMove} onMouseLeave={onLeave}>
      <div className="pf-tilt-glare" />
      {children}
    </div>
  );
}

